def greet(name, greeting="Привет"):
    """Возвращает приветствие: greeting, name!"""
    return f"{greeting}, {name}!"

def average(*numbers):
    if not numbers:
        return 0.0
    return sum(numbers) / len(numbers)

def make_report(title, *rows, footer=None, indent="  "):
    lines = [title]
    for row in rows:
        lines.append(indent + row)
    lines.append(footer if footer is not None else "—")
    return "\n".join(lines)

